// headerRowLabel states where the column titles were found, or that they were
// not, which changes how every row below should be read.
func headerRowLabel(structure catalog.FileStructure) string {
	if structure.Positional || structure.HeaderRow <= 0 {
		return "غير موجود — قراءة بالترتيب"
	}
	return fmt.Sprintf("الصف %d", structure.HeaderRow)
}

